('av_oON4JtnSWmEqkrw-yedy5JRPO64Va7YZIkY8tpq0-Jhi3NT339k8qcU84g1z3ZytGNAPtp7VR3VBqrA','霜花店',2008,'movie','韩国','韩语','["爱情","剧情爱情同性历史"]','["赵寅成朱镇模宋智孝林周焕沈智浩鲁敏宇李豊运","李豊运","林周焕","鲁敏宇","沈智浩","宋智孝","赵寅成","朱镇模"]','["庾河"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/34/3480b2f08b85f70c2a4f0f5a117f0b1e95c0fb9057e57f96f485d6ca0332eb71.webp',NULL,'高丽末年,亲卫军“健龙卫”对高丽王(朱镇模 饰)忠心耿耿,誓死保卫王的安全,其首领洪麟(赵仁成 饰)是王的宠臣,两个相伴多年,关系甚为亲密。远嫁而来的蒙古宝丽公主(宋智孝 饰)倍受冷落,多年来无一子嗣。元朝以高丽国后继无人为由,企图另立新王,把现在的高丽王赶下王位。无奈之下,王只能让自己宠爱的臣子和自己名存实亡的王妃行房,期望王妃怀孕生子,以求让元朝再无易帝的借口。洪麟与王妃初识男欢女爱之欢娱,竟暗生情愫,背着王多次偷偷幽会。王感觉到了洪麟的变化,但还是试图使两人的关系回到过去,可是当他亲眼目睹了王妃和洪麟的偷情之后,盛怒之下对洪麟施行宫刑,自此,三人关系陷入了不可挽回的境地。','高清',1,1,109.12,'最近上线 正片'),
('av_oPBlRUNNaWcgvbiWPGm3J1Udsoq9wK_G0WVJi9hXn8Ntcj85YanTmnLP73vzgGqf7T8eexYfRqAu4ys','黑岛监狱',2026,'series','中国大陆','国语','["国产剧","国产","连续剧","剧情","犯罪","悬疑","连续","警匪罪案","刑侦破案","电视剧(B站)","电视剧"]','["盖玥希","吴晓亮","贾青","孙亮","车保罗","刘牧","王志刚","张国强","张晶伟","张林","马敬涵","杨子骅"]','["杨岱岳","未录入"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/4a/4a2a7e29192d7b23e52d1724c4e5d2e00971218a895106ee31bea94d2a9d121c.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/96/9636288bbf38e3fe0514ed0274cf1679a8f098bd8879e7220f8368ceab764125.webp','凌东国刑警廉明为了破获边境人口失踪案,也前往黑岛监狱卧底查案。南岭国退役特种兵文傍为了营救和自己相依为命的雅醇母女,被迫进入黑岛监狱服刑。狱中二人从互相敌对到彼此扶持,互助协作,勇敢对抗黑帮势力的同时,还要机智化解特殊身份给他们带来的重重危机。就在二人逐步揭开监狱犯罪真相的同时,一场更大的危险正在渐渐靠近......','全16集',16,16,119.58,'2026-11-08T09:26:15.104Z'),
