('av_qyQFpqfDIC5RAioiGdUO8L3MdQ2lX9Ksump4IAGKS5o2cKUIDPWvPKa_541lt9vE43_k6w1skiPpNgo','功夫学徒之走读中国',2020,'variety','中国大陆','国语','["大陆综艺","真人秀","综艺"]','[]','[]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/58/588ee89a309246438519b0e996f270255192e0afd75881afdf3311e927945bc4.webp',NULL,'节目分别邀请来自世界各地的十位学徒来感受中国农村的各色风貌与发展现状。不同文化背景的学徒们,以各自不同的文化视角与表达方式,体验了诸多有代表性的中国职业,带来了更为丰富的文化碰撞。','第10集',10,10,54.1,'最近更新 第10集'),
('av_qz3uEuO7M7KvO7Nq7A3soLopBFYWM3thrWm9uXXOTaMLoy-a0GQFacsUctOUJeYS0BsICoFTwrIppQM','招魂',2013,'movie','美国','英语','["恐怖","悬疑","惊悚","剧情","4K电影"]','["朗·里维斯顿","莉莉·泰勒","帕特里克·威尔森","艾米·蒂普顿","哈蕾·麦克法兰","凯拉·迪弗","玛丽恩·盖约特","麦肯吉·弗依","莫甘娜·布里吉尔斯","乔伊·金","山农·库克","珊莉·卡斯韦尔"]','["温子仁","詹姆斯·温"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/4c/4c6420c3a9913fc5e12bb35af3a05396c0b4087b05727f822e58d5ca2db618c7.webp','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/7d/7d35c39aba3318f0fcce641921ae7ffc642d73b530c446079e500910c44343b3.webp','20世纪七十年代,罗杰(朗·里维斯顿 Ron Livingston 饰)与卡罗琳(莉莉·泰勒 Lili Taylor 饰)两夫妇带着他们五个可爱美丽的女儿,搬到了位于罗德岛哈瑞斯维尔的一幢旧宅居住。房屋虽然古旧沧桑,历史悠久,但是却让佩隆一家体会到回归田园的快乐与喜悦。谁知好景不长,接二连三的怪异事件相继出现,令女孩们惊声尖叫,也让佩隆夫妇的神经绷到极点。为此,他们辗转找到当时最负盛名的沃伦夫妇。 丈夫埃德(帕特里克·威尔森 Patrick Wilson 饰)是天主教会唯一认可的驱魔师,妻子洛琳(维拉·法米加 Vera Farmiga 饰)则拥有窥见灵体的能力。他们不费吹灰之力便确定这座阴气十足的大房子的症结所在,而为了征得教会除灵的许可,他们必须深入期间搜集恶灵存在的证据......','高清',1,1,111.68,'最近上线 正片');
INSERT INTO shows(id,title,year,content_kind,area,language,genres,actors,directors,poster,backdrop,description,remarks,episode_count,available_episode_count,heat_value,updated_at) VALUES
('av_r-zZRAsfzNfWLBnCJCIUFrX1ejaiy2Fr9fOC7Jm7sL1uQ6szZGz6vz7-KknZFJzVrNTfWC-1EOlAONQ','聊斋艳谭之灯草和尚',NULL,'movie',NULL,NULL,'["剧情"]','["陈宝莲","成奎安","何家驹","黄德斌","植敬雯"]','["黎继明"]','https://gimg0.baidu.com/gimg/app=2001&n=0&g=0n&fmt=webp&src=img.baipiaozhe.com/assets/images/0f/0f4981b573ce26ec5fba368dd1a583cf53a80717a75a759daef7c0de2749906b.webp',NULL,'侠士朱仲与未婚妻柳丝丝,路过古庙,结识了可将自己缩小的灯草和尚,彼此甚为投契。是夜,朱仲发现古庙内一璧画中的美女,神态醉人,令朱甚为倾心,遂求教于灯草,灯草见朱一片痴心,便助其入画。朱仲入画后,见美女绮梦(画中人)与二妹妹春梦、玉梦在玩耍,朱、绮二人一见订情,但绮却常流露不安之情。 原来此事是由一魔头摆布,欲借朱仲消灭魔界中的守护神一甲元神,魔头奸计得逞后,欲杀朱仲,但绮梦对朱已动情,决与春梦合谋救朱出画,几经辛苦,终救朱仲出画,魔头获悉后,杀春梦,囚绮梦。朱仲出画后受伤,灯草和尚与柳丝丝合力救之,醒后仍对绮念念不忘,柳虽不悦,仍愿与灯草、朱仲入画相救。三人入画后,与魔头展开人魔大战,终杀魔头,救出绮梦,但柳丝丝亦伤重不治,临死前愿借肉身与绮梦还阳,成全二人。','高清',1,1,106.17,'最近上线 正片'),
